const BASE = "https://api.lokalise.com/api2";
const PID = "31393214664f295f94dd86.76792605";
const IDS = "640,767,666,10154,673,734,10152";
const TOTAL = 17522, LIMIT = 200;
const out = [];
for (let p = 1; p <= Math.ceil(TOTAL / LIMIT); p++) {
  out.push({ json: { page: p, url: BASE + "/projects/" + PID + "/keys?limit=" + LIMIT + "&page=" + p
    + "&include_translations=1&filter_translation_lang_ids=" + IDS } });
}
return out;

const TARGETS = ['da', 'de', 'et', 'fr', 'it', 'lt'];
const NOAUTOFIX = { de: true };
const MINLOWER = 5, CAPRATIO = 3;
const LEGAL = /(terms_and_conditions|privacy|cookie|refund|disclaimer|imprint)/i;
const ADDRESSY = /(\bSTE\b|\bBlvd\b|\b\d{4,6}\b,|\b\d+(st|nd|rd|th)\b|https?:)/;

function toks(s) {
  const out = []; const re = /\S+/g; let m;
  while ((m = re.exec(String(s || ''))) !== null) out.push([m[0], m.index]);
  return out;
}
function core(t) { return t.replace(/^[^\p{L}]+|[^\p{L}]+$/gu, ''); }
function isCap(w) { const f = w.charAt(0); return f === f.toUpperCase() && f !== f.toLowerCase(); }
function isTagOnly(t) { return /^<[^>]*>$/.test(t); }
function starts(tk) {
  const S = { 0: true };
  for (let i = 1; i < tk.length; i++) {
    const p = tk[i - 1][0];
    if (/[.!?:;]$/.test(p)) S[i] = true;
    else if (/[\u25cf\u2022\u25aa\u2023*>]$/.test(p)) S[i] = true;
    else if (/^\(\s*[\p{L}\d]{1,3}\s*\)$/u.test(p)) S[i] = true;
    else if (/^\d+[.)]$/.test(p)) S[i] = true;
    else if (isTagOnly(p)) S[i] = true;
  }
  return S;
}
function profile(s) {
  const tk = toks(s), S = starts(tk);
  let caps = 0, words = 0;
  for (let i = 0; i < tk.length; i++) {
    if (S[i] || isTagOnly(tk[i][0])) continue;
    const c = core(tk[i][0]);
    if (!c || c.length < 2 || c === c.toUpperCase()) continue;
    words++;
    if (isCap(c)) caps++;
  }
  return { caps: caps, words: words };
}

const items = $input.all();
const rows = []; const errors = []; let keys_seen = 0;
for (const it of items) {
  const r = it.json || {};
  const b = r.body !== undefined ? r.body : r;
  if (!Array.isArray(b.keys)) { errors.push({ status: r.statusCode }); continue; }
  for (const k of b.keys) {
    if (k.is_archived) continue;
    keys_seen++;
    let en = ''; const t = {};
    for (const tr of (k.translations || [])) {
      if (tr.language_iso === 'en') { en = tr.translation || ''; continue; }
      if (TARGETS.indexOf(tr.language_iso) === -1) continue;
      if (tr.translation && String(tr.translation).trim()) {
        t[tr.language_iso] = { v: tr.translation, rev: tr.is_reviewed, fz: tr.is_fuzzy,
          cs: (tr.custom_translation_statuses || []).map(s => s.status_id) };
      }
    }
    if (!en || !Object.keys(t).length) continue;
    rows.push({ id: k.key_id, k: (k.key_name && k.key_name.web) || '', en: en, t: t });
  }
}

const freq = {};
for (const iso of TARGETS) freq[iso] = {};
for (const r of rows) {
  for (const iso of Object.keys(r.t)) {
    const tk = toks(r.t[iso].v), S = starts(tk), F = freq[iso];
    for (let i = 0; i < tk.length; i++) {
      if (isTagOnly(tk[i][0])) continue;
      const c = core(tk[i][0]);
      if (!c || c.length < 2 || c === c.toUpperCase()) continue;
      const key = c.toLowerCase();
      if (!F[key]) F[key] = { lower: 0, capNonInit: 0 };
      if (isCap(c)) { if (!S[i]) F[key].capNonInit++; } else F[key].lower++;
    }
  }
}

const per = {}; const samples = []; const fixes = []; const triage = [];
for (const iso of TARGETS) per[iso] = { filled: 0, src_title: 0, suspect: 0, fixable: 0, legal: 0, addressy: 0, no_safe_token: 0, detect_only: 0 };
for (const r of rows) {
  const S0 = profile(r.en);
  if (!(S0.caps >= 2 && S0.words >= 2 && S0.caps / S0.words >= 0.5)) {
    for (const iso of Object.keys(r.t)) per[iso].filled++;
    continue;
  }
  const isLegal = LEGAL.test(r.k);
  for (const iso of Object.keys(r.t)) {
    const A = per[iso]; A.filled++; A.src_title++;
    const v = r.t[iso].v;
    const T = profile(v);
    if (!(T.caps >= 2 && T.words >= 2 && T.caps / T.words >= 0.5)) continue;
    A.suspect++;
    if (NOAUTOFIX[iso]) { A.detect_only++; continue; }
    if (isLegal) { A.legal++; triage.push({ iso: iso, reason: 'legal defined terms', id: r.id, k: r.k, en: r.en.slice(0, 90), cur: v.slice(0, 120) }); continue; }
    if (ADDRESSY.test(v)) { A.addressy++; triage.push({ iso: iso, reason: 'address or url', id: r.id, k: r.k, en: r.en.slice(0, 90), cur: v.slice(0, 120) }); continue; }
    const tk = toks(v), SS = starts(tk), F = freq[iso];
    const edits = []; let blocked = 0;
    for (let i = 0; i < tk.length; i++) {
      if (SS[i] || isTagOnly(tk[i][0])) continue;
      const tokTxt = tk[i][0], idx = tk[i][1];
      if (/\d/.test(tokTxt)) { blocked++; continue; }
      const c = core(tokTxt);
      if (!c || c.length < 2 || c === c.toUpperCase() || !isCap(c)) continue;
      const f = F[c.toLowerCase()] || { lower: 0, capNonInit: 0 };
      if (f.lower >= MINLOWER && f.lower > CAPRATIO * f.capNonInit) {
        const off = tokTxt.indexOf(c);
        edits.push({ at: idx + off, ch: c.charAt(0) });
      } else blocked++;
    }
    if (!edits.length) { A.no_safe_token++; triage.push({ iso: iso, reason: 'no token safe to lowercase', id: r.id, k: r.k, en: r.en.slice(0, 90), cur: v.slice(0, 120) }); continue; }
    let outStr = v;
    edits.sort((a, b2) => b2.at - a.at);
    for (const e of edits) outStr = outStr.slice(0, e.at) + e.ch.toLowerCase() + outStr.slice(e.at + 1);
    if (outStr === v) { A.no_safe_token++; continue; }
    A.fixable++;
    fixes.push({ id: r.id, iso: iso, k: r.k, en: r.en, from: v, to: outStr,
      lowered: edits.length, blocked: blocked, rev: r.t[iso].rev, fz: r.t[iso].fz, cs: r.t[iso].cs });
    if (samples.length < 30) samples.push({ iso: iso, k: r.k.slice(0, 55), en: r.en.slice(0, 50), from: v.slice(0, 72), to: outStr.slice(0, 72), blocked: blocked });
  }
}
return [{ json: {
  pages: items.length, errors: errors, keys_seen: keys_seen, rows: rows.length,
  summary: TARGETS.map(iso => ({ iso: iso, ...per[iso] })),
  total_fixes: fixes.length, total_triage: triage.length,
  samples: samples, fixes: fixes, triage: triage.slice(0, 400)
} }];
